<script lang="ts">
  import { t as uiText } from './i18n.js';
  import {memoryTypes,validateMemorySpecs} from './memory-values.js';
  import type {Manifest,MemorySpec,MemoryType} from './types.js';
  let {manifest,onchange}: {manifest:Manifest;onchange:(fields:Record<string,MemorySpec>)=>void}=$props();
  let name=$state(''),address=$state(''),type=$state<MemoryType>('u8'),error=$state(''),mode=$state('direct');
  function save(next:Record<string,MemorySpec>){try{validateMemorySpecs(next);onchange(next);error='';return true;}catch(e){error=e instanceof Error?e.message:String(e);return false;}}
  function change(key:string,patch:Partial<MemorySpec>){const spec=manifest.values?.[key];if(spec)save({...manifest.values,[key]:{...spec,...patch}});}
  function add(){if(Object.hasOwn(manifest.values??{},name.trim())){error=$uiText("Tên trường đã có.");return;}const spec:MemorySpec=mode==='pointer'?{ptr:address.trim(),offset:0,type}:{addr:address.trim(),type};if(save({...manifest.values,[name.trim()]:spec})){name='';address='';}}
</script>
<details open class="memory-fields"><summary>{$uiText("Trường đọc từ RAM (")}{Object.keys(manifest.values??{}).length})</summary><p>{$uiText("Khai báo địa chỉ một lần; trường xuất hiện trong danh sách gắn dữ liệu cho chữ/thanh chỉ số. Pack xuất ra dùng chính cấu hình này.")}</p>
{#each Object.entries(manifest.values??{}) as [key,spec]}<div class="memory-field"><strong>{key}</strong><button aria-label={$uiText("Xóa trường RAM {0}", key)} onclick={()=>{const next={...manifest.values};delete next[key];save(next);}}>{$uiText("×")}</button><label>{spec.ptr!=null?$uiText("Địa chỉ chứa con trỏ"):$uiText("Địa chỉ hex")}<input aria-label={$uiText("Địa chỉ trường {0}", key)} value={spec.addr??spec.ptr} onchange={(e)=>change(key,spec.ptr!=null?{ptr:e.currentTarget.value.trim()}:{addr:e.currentTarget.value.trim()})} /></label><label>{$uiText("Kiểu đọc")}<select aria-label={$uiText("Kiểu trường {0}", key)} value={spec.type} onchange={(e)=>change(key,{type:e.currentTarget.value as MemoryType})}>{#each Object.keys(memoryTypes) as t}<option value={t}>{t}</option>{/each}</select></label>{#if spec.ptr!=null}<label>Offset<input type="number" value={spec.offset??0} onchange={(e)=>change(key,{offset:Number(e.currentTarget.value)})} /></label>{/if}<label>Mask (hex)<input value={spec.mask??''} placeholder="FF" onchange={e=>change(key,{mask:e.currentTarget.value.trim()||undefined})} /></label><label>Shift<input type="number" min="0" max="31" value={spec.shift??0} onchange={e=>change(key,{shift:Number(e.currentTarget.value)})} /></label>{#if spec.mask!=null||spec.shift!=null}<small>Mask: {spec.mask??$uiText("không")} · Shift: {spec.shift??0} {$uiText("(giữ cấu hình đã nhập)")}</small>{/if}</div>{/each}
<div class="new-field"><label>{$uiText("Cách đọc")}<select bind:value={mode}><option value="direct">{$uiText("Địa chỉ trực tiếp")}</option><option value="pointer">{$uiText("Con trỏ + offset")}</option></select></label><label>{$uiText("Tên trường")}<input aria-label={$uiText("Tên trường RAM mới")} bind:value={name} placeholder="hp" /></label><label>{$uiText("Địa chỉ hex")}<input aria-label={$uiText("Địa chỉ RAM mới")} bind:value={address} placeholder="0x02000000" /></label><label>{$uiText("Kiểu")}<select aria-label={$uiText("Kiểu trường RAM mới")} bind:value={type}>{#each Object.keys(memoryTypes) as t}<option value={t}>{t}</option>{/each}</select></label><button onclick={add}>{$uiText("＋ Thêm trường RAM")}</button></div>
{#if error}<p class="error" role="alert">{$uiText(error)}</p>{/if}{#if manifest.script}<p>{$uiText("Pack có Lua: nguồn trực tiếp dùng kết quả update() từ companion được gán trong GBA Duo Plus.")}</p>{/if}</details>
<style>.memory-fields{background:#29364a;border:1px solid #475b78;border-radius:5px;padding:0 12px;margin:15px 0}.memory-fields summary{font-size:13px}.memory-fields p{font-size:11px}.memory-field{display:grid;grid-template-columns:1fr 100px;gap:7px;padding:12px 0;border-top:1px solid #44536a}.memory-field>strong{color:#a9cdee}.memory-field>button{justify-self:end;padding:3px 8px}.memory-field label{margin:0;font-size:11px}.memory-field input,.memory-field select,.new-field input,.new-field select{font-size:12px}.memory-field small{grid-column:1/-1;color:#a8bbd4}.new-field{display:flex;gap:8px;align-items:end;flex-wrap:wrap;border-top:1px solid #44536a;padding:10px 0}.new-field label{flex:1;min-width:100px;margin:0;font-size:11px}.new-field button{font-size:11px}</style>
